      "html_path": "works/athanasius-serapion-1/index.html#p-3",
      "label": "세라피온에게 보낸 제1서신 3",
      "location": "3",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:8e626e5ec59d17ca91775587bd4c36d700b50bd39653f156c8d82f74b4c04085",
        "text": "Πόθεν τούνυν ὑμῖν, ὦ οὗτοι, τῆς τοσαύτης τόλμης ἡ πρόφασις, ὥστε μὴ φοβηθῆναι τὸ ὑπὸ τοῦ Κυρίου εἰρημένον: «Ὁς δ’ ἂν βλασφημήσῃ εἰς τὸ Πνεῦμα τὸ ἅγιον, οὐκ ἔχει ἄφεσιν οὔτε ἐν τῷ αἰῶνι τούτῳ, οὔτε ἐν τῷ μέλλοντι; » Οἱ μὲν γὰρ Ἀρειανοί, καίτοι τὴν ἔνσαρκον παρουσίαν τοῦ Λόγου καὶ τὰ ἐπ’ αὐτὴν εἰρημένα μὴ νοήσαντες, ὅμως ἐξ αὐτῶν πρόφασιν λαβόντες εἰς τὴν ἑαυτῶν αἵρεσιν, καὶ οὕτως ἠλέγχθησαν θεομάχοι καὶ ὡς ἀληθῶς ἀπὸ γῆς κενολογοῦντες. Ὑμεῖς δὲ πόθεν ἠπατήθητε; παρὰ τίνων ἀκούσαντες, ἢ τίς ὁ τρόπος τῆς τοιαύτης ὑμῶν πλάνης; Ἀνέγνωμεν, φασίν, ἐν τῷ προφήτῃ Ἀμώς, λέγοντος τοῦ Θεοῦ, «Ὅτι Ἰδοὺ ἐγὼ στερεῶν βροντὴν, καὶ κτίζων πνεῦμα, καὶ ἀπαγγέλλων εἰς ἀνθρώπους τὸν Χριστὸν αὐτοῦ· ποιῶν ὄρθρον καὶ ὀμίχλην, καὶ ἐπιβαίνων ἐπὶ τὰ ὑψηλὰ τῆς γῆς, Κύριος ὁ Θεὸς ὁ παντοκράτωρ ὄνομα αὐτῷ. » Καὶ ἔνθεν ἐπείσθημεν τοῖς Ἀρειανοῖς λέγουσιν κτίσμα εἶναι τὸ Πνεῦμα τὸ ἅγιον. Εἴτα τὸ μὲν παρὰ τῷ Ἀμώς ἀνέγνωτε· τὸ δὲ ἐν ταῖς Παροιμίαις λεγόμενον, « Κύριος ἐκτισά με ἀρχὴν ὁδῶν αὐτοῦ εἰς ἔργα αὐτοῦ, » οὐκ ἀνέγνωτε, ἢ ἀνέγνωτε; Καὶ τοῦτο μὲν, ὡς ἔχει ἀληθείας, ἐρμηνεύετε, ἵνα μὴ εἴπητε κτίσμα τὸν Λόγον· τὸ δὲ ἐν τῷ προφήτῃ οὐχ ἐρμηνεύετε, ἀλλ’ ἀπλῶς ἀκούοντες « πνεῦμα, » ἐνομίσατε λέγεσθαι κτίσμα τὸ Πνεῦμα τὸ ἅγιον; Καίτοι ἐν μὲν ταῖς Παροιμίαις φανερῶς ἡ Σοφία λέγουσα ἐστι τὸ, « ἐκτισά με; » καὶ ὅμως καλῶς γε ποιούντες, ἐρμηνεύετε τὸ ῥῆτον, ἵνα μὴ δημιουργὸν Σοφίαν ἐν τοῖς κτίσμασι συναριθμήτε. Τὸ δὲ ἐν τῷ προφήτῃ ῥητὸν οὐκ ἔχει γνώρισμα περὶ τοῦ ἁγίου Πνεύματος, ἀλλ’ ἀπλῶς εἴρηται περὶ πνεύματος. Πῶς οὖν, καίτοι πλείστης οὕσης διαφορᾶς ἐν ταῖς Γραφαῖς περὶ πνευμάτων, καὶ δυναμένου τοῦ ῥητοῦ τὴν ἰδίαν διάνοιαν ἔχειν ὀρθήν, ὑμεῖς, ὡς φιλονεικοῦντες ἢ ὡς ὑπὸ δήγματος τοῦ Ἀρειανοῦ ὄφεως βλαβέντες, τὸ Πνεῦμα τὸ ἅγιον εἰρῆσθαι παρὰ τοῦ Ἀμώς νομίζετε, ἵνα μόνον τοῦ φρονεῖν κτίσμα μὴ ἐπιλάθησθε;"
      },
      "title": "세라피온에게 보낸 제1서신",
      "translation": {
        "notes": [
          "아모스 4:13은 칠십인역 문구로 인용된다. 그리스어 πνεῦμα는 영과 바람을 모두 뜻한다. 인용문에서는 상대가 읽은 대로 영으로 옮겼으며, 이 영을 바람이나 사람의 영으로 읽을 수 있다는 점은 아타나시우스가 뒤에서 용례를 모아 논증한다. 이 인용에는 ‘자기의 그리스도를 사람들에게 알린다’는 표현이 들어 있어 히브리어 본문에 따른 한국어 성경과 문구가 다르다.",
          "잠 8:22의 ‘창조하셨다’를 문맥에 맞게 해석하는 상대에게 아모스의 πνεῦμα도 문맥에 따라 해석하라고 요구한다. 성령 모독에 대한 경고는 마 12:31-32의 말씀에 따른다."
        ],
        "revision_id": "sha256:fce9fba253485dd8d831a160f0685c2e882258fb31be4bc02a8394210e755045",
        "text": "당신들은 무슨 근거로 이토록 무모해졌습니까? 주님께서 하신 다음 말씀도 두려워하지 않습니까? “성령을 모독하는 자는 이 시대에도 오는 시대에도 용서를 받지 못한다.” 아리우스파는 말씀이 육신으로 오신 일과 그 일에 관해 하신 말씀을 이해하지 못했습니다. 그럼에도 그 말씀들을 자기 이단의 구실로 삼았고, 그로써 하나님과 싸우며 참으로 땅에 속한 헛소리를 하는 자들로 드러났습니다. 당신들은 무엇에 속았습니까? 누구에게 들었으며, 어떤 비유로 이런 잘못에 빠졌습니까? 그들은 이렇게 말합니다. “우리는 예언자 아모스에게서 하나님이 하신 말씀을 읽었다. ‘보라, 나는 우레를 굳게 하고 영을 창조하며, 자기의 그리스도를 사람들에게 알리고, 새벽과 안개를 만들며 땅의 높은 곳을 밟는 이다. 주 만군의 하나님이 그의 이름이다.’ 이 말씀 때문에 우리는 성령이 피조물이라는 아리우스파의 주장에 설득되었다.” 그러면 당신들은 아모스의 말씀은 읽었으면서, 잠언에 나오는 “주께서 자기 일을 위하여 나를 자기 길의 시작으로 창조하셨다”는 말씀은 읽지 않았습니까, 아니면 읽었습니까? 그 말씀은 그 안의 진리에 맞게 해석하여 말씀을 피조물이라고 하지 않으면서, 예언자의 말씀은 해석하지 않고 ‘영’이라는 말만 듣고서, 성령을 피조물이라고 한 것으로 생각했습니까? 잠언에서는 “나를 창조하셨다”고 말하는 이가 분명히 지혜입니다. 그럼에도 당신들은 창조하는 지혜를 피조물들과 같은 부류에 넣지 않으려고 그 구절을 해석합니다. 그렇게 하는 것은 옳습니다. 그런데 예언자의 구절에는 성령을 가리킨다는 표지가 없고, 그저 ‘영’에 관해 말했을 뿐입니다. 성경에서는 ‘영들’이라는 말이 매우 다양한 뜻으로 쓰이며, 이 구절도 그 문맥에 맞는 올바른 의미로 이해할 수 있습니다. 그런데 당신들은 다투기를 좋아해서입니까, 아니면 아리우스파라는 뱀에게 물려 해를 입어서입니까? 왜 아모스가 성령을 말한 것으로 생각합니까? 성령이 피조물이라는 생각만은 잊지 않으려는 것입니까?"
      },
      "work_id": "athanasius-serapion-1",
