      "label": "세라피온에게 보낸 제4서신 14",
      "location": "14",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:dcc7349fc41949861adaa95f8a4ab8f3dbcb23f558bd9629cb2b44d4830c49ad",
        "text": "Τοιαῦτα δὴ οὖν μοι λογιζομένῳ, μεῖζον ἀπαντᾷ τὸ βάθος τῆς ἐν τῷ ῥητῷ διανοίας· καὶ διὰ τοῦτο πολλά πρότερον παρακαλέσας τὸν ἐπὶ τὸ φρέαρ καθεσθέντα, καὶ ἐπὶ τὴν θάλασσαν περιπατήσαντα Κύριον, ἐπὶ τὴν οἰκονομίαν λοιπὸν τὴν ἐν αὐτῷ γενομένην ὑπὲρ ἡμῶν ἀνέρχομαι, τάχα πως ἐξ αὐτῆς τὸν ἐν τῷ ἀναγνώσματι νοῦν λαβεῖν δυνηθῶ. Πᾶσα τοίνυν ἡ θεία Γραφὴ ταύτην εὐαγγελίζεται καὶ κηρύττει, μάλιστα δὲ ὁ μὲν Ἰωάννης λέγων· « Ὁ Λόγος σὰρξ ἐγένετο, καὶ ἐσκήνωσεν ἐν ἡμῖν· » ὁ δὲ Παῦλος γράφων· « Ὃς ἐν μορφῇ Θεοῦ ὑπάρχων, οὐχ ἁρπαγμὸν ἡγήσατο τὸ εἶναι ἴσα Θεῷ· ἀλλ’ ἑαυτὸν ἐκένωσεν, μορφὴν δούλου λαβὼν, καὶ σχήματι εὐρεθεὶς ὡς ἄνθρωπος. Ἐταπείνωσεν ἑαυτόν, ὑπήκοος γενόμενος μέχρι θανάτου, θανάτου δὲ σταυροῦ. » Διὰ τοῦτο γὰρ Θεὸς ὢν καὶ ἄνθρωπος γενόμενος, ὡς μὲν Θεὸς ἤγειρε νεκρούς, καὶ λόγῳ πάντας θεραπεύων, μετέβαλε καὶ τὸ ὕδωρ εἰς οἶνον· οὐ γὰρ ἦν ἀνθρώπου ταῦτα ἔργα· ὡς δὲ σῶμα φορῶν, ἐδίψα καὶ ἐκοπία, καὶ ἔπασχεν· οὐ γὰρ ἦν ἴδια ταῦτα τῆς θεότητος. Καὶ ὡς μὲν Θεὸς ἔλεγεν· « Ἐγὼ ἐν τῷ Πατρὶ, καὶ ὁ Πατὴρ ἐν ἐμοί· » ὡς δὲ σῶμα φορῶν, ἤλεγχε τοὺς Ἰουδαίους: « Τί με ζητεῖτε ἀποκτεῖναι, ἄνθρωπον, ὃς τὴν ἀλήθειαν ὑμῖν λελάληκα, ἣν ἤκουσα παρὰ τοῦ Πατρός; » Ἐγίνετο δὲ ταῦτα οὐ διῃρημένως κατὰ τὴν τῶν γινομένων ποιότητα, ὥστε τὰ μὲν τοῦ σώματος χωρὶς τῆς θεότητος, τὰ δὲ τῆς θεότητος χωρὶς τοῦ σώματος δείκνυσθαι· συνημμένως δὲ πάντα ἐγίνετο, καὶ εἷς ἦν ὁ ταῦτα ποιῶν Κύριος παραδόξως τῇ ἑαυτοῦ χάριτι. Ἔπτυσε γὰρ ἀνθρωπίνως, καὶ τὸ πτύσμα ἦν ἔνθεον· ἐν αὐτῷ γὰρ ἐποίει τοὺς ὀφθαλμοὺς τοῦ ἐκ γενετῆς τυφλοῦ ἀναβλέπειν. Καὶ δεῖκνύναι δὲ θέλων ἑαυτὸν Θεόν, ἀνθρωπίνῃ γλώττῃ τοῦτο σημαίνων ἔλεγεν: « Ἐγὼ καὶ ὁ Πατὴρ ἕν ἐσμεν » καὶ μόνον δὲ θέλων ἐθεράπευσεν. Τὴν δὲ ἀνθρωπίνην ἐκτείνων χεῖρα, ἤγειρε τὴν πενθεράν Πέτρου πυρέσσουσαν, καὶ τὴν τοῦ ἀρχισυναγώγου θυγατέρα ἤδη τελευτήσασαν ἐκ τῶν νεκρῶν ἀνέγειρεν."
      },
      "title": "세라피온에게 보낸 제4서신",
      "translation": {
        "notes": [
          "성육신의 경륜을 통해 복음서의 말씀을 해석한다. 요 1:14와 빌 2:6-8을 인용하고, 주님의 신적 일들과 몸에 따른 경험을 함께 설명한다.",
          "침을 뱉음과 시력 회복, 인간의 말과 신적 권능, 손을 내밈과 죽은 이의 부활을 연결한다. 이 일들을 행하시는 주님이 한 분이라는 점을 강조한다."
        ],
        "revision_id": "sha256:6d962afe55269c81b8408eba9ff5930221f68216811de617b17539f6e423de93",
        "text": "이런 생각을 하니 말씀에 담긴 뜻의 깊이가 내게 더 크게 다가옵니다. 그래서 먼저 간절히 청하며, 우물가에 앉으셨고, 바다 위를 걸으셨던 주님께 기도한 뒤, 이제 그분 안에서 우리를 위해 이루어진 구원의 경륜을 살펴보려 합니다. 어쩌면 거기서 읽은 말씀의 뜻을 알 수 있을 것입니다. 하나님의 성경 전체가 이 경륜을 기쁜 소식으로 전하고 선포합니다. 특히 요한은 말합니다. “말씀이 육신이 되어 우리 가운데 거하셨다.” 바울은 씁니다. “그분은 하나님의 형체로 계셨으나, 하나님과 동등하게 계심을 빼앗아 취할 것으로 여기지 않으셨다. 자신을 비우셨다. 종의 형체를 취하시고, 외양으로는 사람과 같이 나타나셨다. 자신을 낮추시고, 죽기까지, 곧 십자가에서 죽기까지 순종하셨다.” 이 때문에 그분은 하나님으로 계시며 사람이 되셨고, 하나님으로서 죽은 이들을 일으키시며, 말씀으로 모든 이들을 고치시고, 물을 포도주로 바꾸기도 하셨습니다. 이 일들은 사람의 일이 아니었기 때문입니다. 몸을 지니신 분으로서는, 목마르고 지치며 고난을 겪으셨습니다. 이 일들은 신성에 고유한 것이 아니었기 때문입니다. 하나님으로서는 말씀하셨습니다. “나는 아버지 안에 있고 아버지는 내 안에 계신다.” 몸을 지니신 분으로서는, 유대인들을 책망하셨습니다. “어째서 너희는 나를 죽이려 하느냐? 나는 너희에게 진리를 말한 사람이다. 아버지에게서 들은 진리를 말하였다.” 이 일들은 일어나는 일의 성격에 따라 분리되어 이루어진 것이 아닙니다. 몸의 일들이 신성에서 떨어져, 신성의 일들이 몸에서 떨어져 드러난 것이 아닙니다. 모든 일이 결합된 채 이루어졌으며, 이 일들을 행하신 주님은 한 분이셨습니다. 그분 자신의 은혜로 놀랍게 행하셨습니다. 그분은 사람처럼 침을 뱉으셨으나, 그 침에는 신적 능력이 있었습니다. 그것으로 태어날 때부터 눈먼 사람의 눈을 보게 하셨기 때문입니다. 또 자신이 하나님이심을 드러내려 하실 때, 사람의 혀로 이를 알리시며 말씀하셨습니다. “나와 아버지는 하나이다.” 또 뜻하시기만 해도 고치셨습니다. 그러면서 사람의 손을 내미시어, 열병을 앓던 베드로의 장모를 일으키시고, 회당장의 딸이 이미 죽었는데도 죽은 이들 가운데서 일으키셨습니다."
      },
