      "html_path": "works/athanasius-serapion-4/index.html#p-22",
      "label": "세라피온에게 보낸 제4서신 22",
      "location": "22",
      "relation": "primary_passage",
      "source": {
        "language": "grc",
        "revision_id": "sha256:c500fe5be682bf33c1f4bef4ad9c0a0dd785e4159f9d116ff40755f0dcb03d07",
        "text": "Ἔδει δὲ τοὺς πονηροὺς ἢ μηδὲ ἐκ τῶν σωματικῶν ἐξουθενεῖν αὐτοὺς ὡς ἄνθρωπον τὸν Κύριον, ἢ δηλονότι καὶ ἐκ τῶν ἔργων Θεὸν αὐτὸν ὁμολογεῖν ἀληθινόν. Ἀλλὰ πάντα διεστραμμένως ἐπράττον· ἄνθρωπον μὲν βλέποντες, ὡς ἀνθρώπῳ ἐλοιδοροῦντο· ἔργα δὲ θεϊκὰ θεωροῦντες, ἠρνοῦντο τὴν Θεότητα, καὶ προσέτρεχον τῷ διαβόλῳ, οἰόμενοι, ὅτι, ταῦτα τολμῶντες, διαδράναι δυνήσονται, ὥστε μὴ κριθῆναι παρ’ αὐτοῦ τοῦ ὑβριζομένου παρ’ αὐτῶν Λόγου. Οἱ μὲν οὖν ἐπαοιδοὶ, καὶ μάγοι, καὶ φαρμακοὶ τοῦ Φαραὼ, καίτοι πλεῖστα ἐπιχειρήσαντες, ὅμως βλέποντες τὰ διὰ Μωϋσέως σημεῖα, καθυφῆκαν, καὶ νῶτα δεδώκασι, λέγοντες δάκτυλον εἶναι Θεοῦ τὸν ταῦτα ποιοῦντα· οἱ δὲ Φαρισαῖοι καὶ οἱ γραμματεῖς, ὅλην τὴν χεῖρα τοῦ Θεοῦ βλέποντες ἐργαζομένην, καὶ πλεῖονα καὶ μεῖζονα θεωροῦντες ἐκείνων τὰ δι’ αὐτοῦ τοῦ Σωτῆρος γινόμενα, τὸν Βεελζεβοὺλ ἔλεγον ταῦτα ποιεῖν, ὃν καὶ οἱ μάγοι, καίτοι ἴδιον αὐτῶν ὄντα, ὅμως ὡμολόγουν μὴ δύνασθαι μηδὲ τὰ τούτων ἐλάττονα ποιεῖν. Τίς οὖν ὑπερβολὴ τῆς τούτων μανίας εἰπεῖν; ἢ τίς, ὡς εἴρηκεν ὁ προφήτης, ὁμοιῶσαί τι ταῖς τούτων ἀσεβείαις δυνήσεται; Ἐδικαίωσαν γὰρ ἐξ ἑαυτῶν καὶ Σοδομίτας· καὶ νενίκηκασιν μὲν τὴν Ἑλλήνων ἀγνωσίαν, ὑπερβάλλουσι δὲ καὶ τῶν μάγων τοῦ Φαραὼ τὴν ἀλογίαν· καὶ πρὸς μόνους τοὺς Ἀρειομανίτας ἔχουσι τὴν σύγκρισιν, ἀλλήλοις εἰς τὴν αὐτὴν ἀσεβείαν συμπίπτοντες. Ἰουδαῖοι μὲν γὰρ βλέποντες διὰ τοῦ Υἱοῦ τὰ τοῦ Πατρὸς ἔργα, τῷ Βεελζεβοὺλ ἀνατιθέασιν αὐτά· Ἀρειανοὶ δέ, καὶ αὐτοὶ τὰ αὐτὰ βλέποντες ἔργα, τοῖς κτίσμασι συναριθμοῦσι τὸν ταῦτα ποιοῦντα Κύριον, φάσκοντες ἐξ οὐκ ὄντων αὐτὸν εἶναι· καὶ, οὐκ ἦν, πρὶν γένηται. Καὶ οἱ μὲν Φαρισαῖοι θεωροῦντες τὸν Κύριον ἐν σώματι διεγόγγυζον λέγοντες· Διὰ τί σὺ, ἄνθρωπος ὢν, ποιεῖς σεαυτὸν Θεόν; οἱ δὲ Χριστομάχοι, βλέποντες αὐτὸν πάσχοντα καὶ κοιμώμενον, βλασφημοῦσι λέγοντες· Ὁ ταῦτα ὑπομείνων οὐ δύναται Θεὸς ἀληθινὸς καὶ ὁμοούσιος εἶναι τοῦ Πατρός. Καὶ ὅλως ἂν τις ἐξετάζειν ἐκ παραλλήλου βούλοιτο τὰς ἀμφοτέρων κακονοίας, εὑρήσει, καθὰ προεῖπον, εἰς τὴν κοιλάδα τῆς ἁλυκῆς παροινίας συμπίπτοντας αὐτοὺς ἀλλήλοις."
      },
      "title": "세라피온에게 보낸 제4서신",
      "translation": {
        "notes": [
          "출애굽기의 파라오의 마술사들과 복음서의 바리새인들을 비교한 뒤, 아리우스의 무리가 아들을 피조물에 포함시키는 주장과 연결한다.",
          "유대인과 이교도 및 아리우스의 무리에 대한 강한 비난은 저자의 논쟁 언어이다. 끝의 ‘악독한 행패의 골짜기’는 κοιλάδα τῆς ἁλυκῆς παροινίας의 비유를 옮긴 표현이다."
        ],
        "revision_id": "sha256:c92de063357b6ff850480c40f97cb247886387ae7ce78bdbefcce6dc3acd8302",
        "text": "그 악한 자들은 다음 중 하나를 했어야 했습니다. 몸의 일들을 근거로 주님을 사람이라며 업신여기지 않거나, 분명 그분의 일들을 근거로 그분을 참 하나님이라고 고백했어야 했습니다. 그러나 모든 일을 비뚤어지게 행했습니다. 그분을 사람으로 보고, 사람을 욕하듯 욕했습니다. 신적 일들을 보고는, 신성을 부인하며, 악마에게 달려갔습니다. 감히 그런 일을 하면 벗어날 수 있다고 생각했습니다. 자기들이 모욕하는 바로 그 말씀에게 심판받지 않을 수 있다고 생각한 것입니다. 파라오의 주문 외는 자들과 마술사들과 주술사들은, 아주 많은 시도를 했는데도, 모세를 통해 일어나는 표적들을 보고는, 물러서고 등을 돌렸습니다. 이 일들을 행하는 것은 하나님의 손가락이라고 말했습니다. 그런데 바리새인들과 서기관들은, 하나님의 손 전체가 일하는 것을 보고, 그때보다 더 많고 큰 일들을 보면서도, 구주 자신을 통해 이루어지는 일들을 보면서도, 베엘제불이 이 일들을 행한다고 했습니다. 마술사들조차 베엘제불을 두고, 그가 자기들 편인데도, 이보다 작은 일들조차 행할 수 없다고 인정했는데 말입니다. 그렇다면 누가 그들의 광기가 얼마나 심한지 말할 수 있겠습니까? 예언자가 말했듯이, 누가 그들의 불경함에 견줄 만한 일을 찾을 수 있겠습니까? 그들은 자기들의 행동으로 소돔 사람들마저 의롭게 보이게 했습니다. 이교도들의 무지도 능가했고, 파라오의 마술사들의 어리석음도 능가합니다. 아리우스에게 미친 무리와만 비교할 수 있습니다. 서로 같은 불경함에 빠지기 때문입니다. 유대인들은 아들을 통해 아버지의 일들이 이루어지는 것을 보고, 그 일들을 베엘제불에게 돌립니다. 아리우스의 무리도 같은 일들을 보면서, 이 일들을 행하시는 주님을 피조물에 포함시킵니다. 그분이 존재하지 않는 것들에서 나왔다고 하며, “그분이 생겨나기 전에는 계시지 않았다”라고 합니다. 바리새인들은 몸 안에 계신 주님을 보고, 불평하며 말했습니다. “어째서 너는 사람이면서 자신을 하나님으로 만드느냐?” 그리스도와 싸우는 자들은, 그분이 고난받고 잠드시는 것을 보고, 모독하며 말합니다. “이런 일들을 겪은 이는, 참 하나님일 수도 아버지와 동일본질일 수도 없다.” 누군가 나란히 살펴보려 한다면, 두 무리의 악한 생각들을 살펴보려 한다면, 앞에서 말한 대로 알게 될 것입니다. 그들이 서로 악독한 행패의 골짜기에 함께 빠져 있음을 알게 될 것입니다."
      },
      "work_id": "athanasius-serapion-4",
